void lock() {
  while (locked.exchange(true,
           std::memory_order_acquire))
    locked.wait(true,     // sleeps
      std::memory_order_relaxed);
}
void unlock() {
  locked.store(false,
               std::memory_order_release);
  locked.notify_one();
}
